import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test("a file of exactly 10 MiB is accepted", { tag: "@DOC-05" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const vendorRes = await member.post("/api/vendors", {
    data: { name: uniqueName("Doc Size"), category: "services", contact_email: "docs@doc-size.example" },
  });
  expect(vendorRes.status(), await vendorRes.text()).toBe(201);
  const { id } = (await vendorRes.json()) as { id: string };
  const buffer = Buffer.alloc(TEN_MIB, "x");
  expect(buffer.length).toBe(TEN_MIB);

  // Act
  const response = await member.post(`/api/vendors/${id}/documents`, {
    multipart: {
      kind: "contract",
      file: { name: "contract-10mib.txt", mimeType: "text/plain", buffer },
    },
  });

  // Assert
  expect(response.status(), await response.text()).toBe(201);
});
